CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.assign_office_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='islamseo10@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_office_owner() FROM PUBLIC;
CREATE TRIGGER office_owner_confirmed AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_office_owner();
CREATE TABLE public.site_documents (id text PRIMARY KEY CHECK(id IN ('published','draft')), content jsonb NOT NULL DEFAULT '{}'::jsonb, revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_documents TO anon; GRANT SELECT,INSERT,UPDATE ON public.site_documents TO authenticated; GRANT ALL ON public.site_documents TO service_role;
ALTER TABLE public.site_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_content ON public.site_documents FOR SELECT TO anon,authenticated USING(id='published');
CREATE POLICY admin_read_content ON public.site_documents FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_write_content ON public.site_documents FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_update_content ON public.site_documents FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.publish_office_content(expected_revision integer) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE doc public.site_documents; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO doc FROM public.site_documents WHERE id='draft' FOR UPDATE; IF doc.revision IS DISTINCT FROM expected_revision THEN RAISE EXCEPTION 'Revision conflict'; END IF; INSERT INTO public.site_documents(id,content,revision,updated_at) VALUES('published',doc.content,doc.revision,now()) ON CONFLICT(id) DO UPDATE SET content=EXCLUDED.content,revision=EXCLUDED.revision,updated_at=EXCLUDED.updated_at; END $$;
REVOKE ALL ON FUNCTION public.publish_office_content(integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.publish_office_content(integer) TO authenticated;
CREATE POLICY admin_media_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='site-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_media_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='site-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='site-media' AND public.has_role(auth.uid(),'admin'));